INSERT INTO material_issues (id, issue_code, branch_id, status, note) SELECT '20000000-0000-4000-8000-000000000001','PX-0001',id,'APPROVED','Dữ liệu mẫu: đã cấp' FROM branches WHERE code='TEST-CN01' ON CONFLICT (issue_code) DO NOTHING;
INSERT INTO material_issue_details (id, issue_id, material_id, material_lot_id, location_id, unit_id, quantity) SELECT '20000000-0000-4000-8000-000000000002', i.id,m.id,l.id,w.id,m.unit_id,5 FROM material_issues i JOIN branches b ON b.id=i.branch_id JOIN warehouse_locations w ON w.branch_id=b.id AND w.name='Kho lạnh' JOIN materials m ON m.code='TEST-NVL001' JOIN material_lots l ON l.material_id=m.id AND l.lot_code='TEST-LO001' WHERE i.issue_code='PX-0001' ON CONFLICT (id) DO NOTHING;
INSERT INTO staff_audits (id,actor_id,action,target_id,detail) SELECT '20000000-0000-4000-8000-000000000003', u.id,'MATERIAL_REQUEST', i.id::text,i.issue_code FROM staff_users u CROSS JOIN material_issues i WHERE u.code='DEMO-KITCHEN' AND i.issue_code='PX-0001' ON CONFLICT (id) DO NOTHING;
INSERT INTO staff_material_returns (id,code,actor_id,branch_id,issue_detail_id,quantity,note,status) SELECT '20000000-0000-4000-8000-000000000004','HT-0001',u.id,i.branch_id,d.id,1,'Dữ liệu lịch sử mẫu','APPROVED' FROM staff_users u JOIN material_issues i ON i.issue_code='PX-0001' JOIN material_issue_details d ON d.issue_id=i.id WHERE u.code='DEMO-KITCHEN' ON CONFLICT (code) DO NOTHING;
INSERT INTO staff_material_returns (id,code,actor_id,branch_id,issue_detail_id,quantity,note,status) SELECT '20000000-0000-4000-8000-000000000005','HT-0002',u.id,i.branch_id,d.id,1,'Dữ liệu lịch sử mẫu','PENDING' FROM staff_users u JOIN material_issues i ON i.issue_code='PX-0001' JOIN material_issue_details d ON d.issue_id=i.id WHERE u.code='DEMO-KITCHEN' ON CONFLICT (code) DO NOTHING;
INSERT INTO staff_material_waste (id,code,actor_id,branch_id,balance_id,quantity,reason,status) SELECT '20000000-0000-4000-8000-000000000006','HH-0001',u.id,w.branch_id,mb.id,0.5,'Nguyên liệu hỏng - dữ liệu mẫu','PENDING' FROM staff_users u JOIN warehouse_locations w ON w.branch_id=u.branch_id JOIN material_balances mb ON mb.location_id=w.id JOIN material_lots l ON l.id=mb.material_lot_id WHERE u.code='DEMO-KITCHEN' AND l.lot_code='TEST-LO001' ON CONFLICT (code) DO NOTHING;
INSERT INTO finished_goods_defects (id,code,branch_id,product_code,quantity,reason,deduct_from_stock,status) SELECT '20000000-0000-4000-8000-000000000007','TPLOI-0001',id,'DEMO-TP01',1,'Hình thức không đạt - dữ liệu mẫu',true,'PENDING' FROM branches WHERE code='TEST-CN01' ON CONFLICT (code) DO NOTHING;
INSERT INTO staff_audits (id,actor_id,action,target_id,detail) SELECT '20000000-0000-4000-8000-000000000008',u.id,'FINISHED_DEFECT_REQUEST',d.id::text,d.code FROM staff_users u CROSS JOIN finished_goods_defects d WHERE u.code='DEMO-KITCHEN' AND d.code='TPLOI-0001' ON CONFLICT (id) DO NOTHING;
INSERT INTO finished_goods_issues (id,code,branch_id,shift_code,status,note) SELECT '20000000-0000-4000-8000-000000000009','PXTP-0001',id,'CA-001','PENDING','Dữ liệu lịch sử mẫu' FROM branches WHERE code='TEST-CN01' ON CONFLICT (code) DO NOTHING;
INSERT INTO finished_goods_issue_details (id,issue_id,product_code,requested_quantity) SELECT '20000000-0000-4000-8000-000000000010',id,'DEMO-TP01',2 FROM finished_goods_issues WHERE code='PXTP-0001' ON CONFLICT (issue_id,product_code) DO NOTHING;
INSERT INTO staff_audits (id,actor_id,action,target_id,detail) SELECT '20000000-0000-4000-8000-000000000011',u.id,'FINISHED_ISSUE_REQUEST',i.id::text,i.code FROM staff_users u CROSS JOIN finished_goods_issues i WHERE u.code='DEMO-KITCHEN' AND i.code='PXTP-0001' ON CONFLICT (id) DO NOTHING;
